class NVHcmWorkCalendarHolidayUpdate extends RunBaseBatch implements BatchRetryable
{
    HcmWorkCalendarHoliday calendarHoliday;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        calendarHoliday
    #endmacro

}

Method.Source:
public Object dialog()
{
    DialogRunbase       dialog = super();

    return dialog;
}

public void run()
{
    #OCCRetryCount
    try
    {
        ttsbegin;
        HcmWorkCalendarGenerationDetail calendarGenerationDetail;
        while select calendarGenerationDetail
            where calendarGenerationDetail.WorkCalendarHoliday == calendarHoliday.Id
                && calendarGenerationDetail.CalendarId != ''
        {
            NVHcmWorkCalendarHolidayUpdate::updateWorkCalendarDaysForHolidays(calendarGenerationDetail);
        }
        ttscommit;

        Info("Operation completed");
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

public static void updateWorkCalendarDaysForHolidays(HcmWorkCalendarGenerationDetail _calendarGenerationDetail)
{
    WorkCalendarDate calendarDate;
    HcmWorkCalendarHolidayLine workCalendarHolidayLine;

    calendarDate.skipDataMethods(true);

    WorkCalendarTable calendarTable = WorkCalendarTable::find(_calendarGenerationDetail.CalendarId);

    update_recordset calendarDate
        setting WorkTimeControl = WorkTimeControl::Closed
        exists join workCalendarHolidayLine
            where calendarDate.CalendarId == calendarTable.CalendarId
            && calendarDate.TransDate == workCalendarHolidayLine.HolidayDate
            && workCalendarHolidayLine.NVNonWorkingDay == NoYes::Yes
            && workCalendarHolidayLine.HcmWorkCalendarHolidayId == _calendarGenerationDetail.WorkCalendarHoliday;

    update_recordset calendarDate
        setting WorkTimeControl = WorkTimeControl::Holiday
        exists join workCalendarHolidayLine
            where calendarDate.CalendarId == calendarTable.CalendarId
            && calendarDate.TransDate == workCalendarHolidayLine.HolidayDate
            && workCalendarHolidayLine.NVNonWorkingDay == NoYes::No
            && workCalendarHolidayLine.HcmWorkCalendarHolidayId == _calendarGenerationDetail.WorkCalendarHoliday;
}

public boolean unpack(container packedClass)
{
    Version version = RunBase::getVersion(packedClass);
    ;
    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = packedClass;
            break;
        default:
            return false;
    }

    return true;
}

public boolean validate(Object _calledFrom = null)
{
    return true;
}

static NVHcmWorkCalendarHolidayUpdate construct()
{
    return new NVHcmWorkCalendarHolidayUpdate();
}

static ClassDescription description()
{
    return "Update holidays and closure on calendar";
}

static void main(Args args)
{
    HcmWorkCalendarHoliday calendarHoliday = args.record() as HcmWorkCalendarHoliday;

    NVHcmWorkCalendarHolidayUpdate update = NVHcmWorkCalendarHolidayUpdate::construct();        
    update.setCalendarHoliday(calendarHoliday);
    if (update.prompt())
    {
        update.runOperation();
    }
}

[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}
